import * as THREE from 'three';

// ------------------------------ CONSTANTES ------------------------------
const CELL=64;                        // grade do terreno
const FX = 0xBEEFCAFEBABE;            // gerador de ruído determinístico
const LW = 7600, LH = 7200;           // tamanho do mundo (unidades/metros)
const CX0=LW/2, CY0=LH/2;             // centro do mundo
const TRIBES = [
  {n:'Lobo Vermelho',c:'#c0392b',d:'Caçadores ferozes dominam as planícies.',cnt:8},
  {n:'Águia Branca',c:'#e67e22',d:'Sentinéis dos céus montanhosos.',cnt:8},
  {n:'Coral Azul',c:'#3498db',d:'Povo ribeirinho do rio central.',cnt:6},
  {n:'Onça Pintada',c:'#27ae60',d:'Guardiões das profundezas florestais.',cnt:8},
  {n:'Montanha Gélida',c:'#16a085',d:'Nômades acostumados à neve e ao gelo.',cnt:6},
  {n:'Ventos do Deserto',c:'#d35400',d:'Bandeiras vermelhas cruzam os areais.',cnt:6},
  {n:'Guarani da Selva',c:'#8e44ad',d:'Mestres das trilhas centenárias.',cnt:8},
  {n:'Pedra do Rochedo',c:'#7f8c8d',d:'Povos antigos das montanhas rochosas.',cnt:6},
];
const TRICOL = TRIBES.map(t=>hexToRgb(t.c));
const BIOHC = {
 0:[.90,.84,.70],1:[.96,.79,.52],2:[.72,.50,.22],3:[.16,.39,.17], // 3 com tom verde mais escuro perto da borda
 4:[.45,.48,.55],5:[.85,.91,.93],6:[.26,.20,.23],
};
const BIODS = ['Cidade','Planície','Savana','Selva','Montanhas','Neve','Rochedo','Rio/Lago'];

// ------------------------------ UTILIDADES ------------------------------
function lerp(a,b,t){return a+(b-a)*t;}
function hexToRgb(h){h=h.slice(1); return [parseInt(h.substr(0,2),16)/255,parseInt(h.substr(2,2),16)/255,parseInt(h.substr(4,2),16)/255];}
function rgbToArray(rgb){return [rgb[0]*255,rgb[1]*255,rgb[2]*255];}
function clamp01(x){return Math.max(0,Math.clamp(x,0,1));}
function norm2(v){const m=Math.sqrt(v.x*v.x+v.y*v.y); return v.length()===0 ? v : new THREE.Vector3(v.x/m,v.y/m,v.z/m);}
function wrap2(v,xhalf,yhalf){
  const s=2*xhalf;
  v.x=((v.x+s)%s)+s<0?v.x+s:-v.x;
  v.y=((v.y+yhalf)%s)+s<0?v.y+s:-v.y;
}
function rand(){return Math.imod(Math.random()*2147483647);}
function hf(v){
  v|=0; v=(-v^v>>>13)|0; v+=(0x5DEECECE61|0)|0; v|=0;
  let t=(v*0xC4FEAbABEDNAE5|0)|(0);
  return ((t^t>>>7)&(1<<52-1))>>>(52-32);
}
function noise2(x,y){
  const a=.5,b=.62;
  const k1=hf(rand()+(x*.5+y*.27)*257 + rand()*313);
  const k2=hf(rand()+(x*1.1+y*1.7)*4194+rand()*7439);
  return lerp(hf(k1>>0),hf(k2>>0),0.5);
}
function wrapPos(v){
  const h=3800; v %= (2*h); return v<h? v-h: v; }

