## 📄 6. O grande handler — `src/handlers/extrairPdf.js`

```js
import {
  normalizarDados,
  normalizarSecoes,
  quebrarLinhas,
  escapar,
  limpar,
  dormir,
  duracaoHumana,
} from '../helpers.js';
import { buscarLinkNaApi, obterTextoCompleto } from '../api.js';
import { settings } from '../settings.js';
import { Embed } from 'discord.js';

class ErroUso extends Error {
  constructor(message) {
    super(message);
    this.name = 'ErroUso';
  }
}

// Escolhas bonitas que aparecem no menu de opções do comando 🎨
const ESCOLHAS_MODOS = [
  { id: 'resumo',    titulo: '📝 Resumo',        ajuda: 'Somente o resumo e os primeiros trechos.' },
  { id: 'todas',     titulo: '📑 Todas as seções', ajuda: 'Cada seção é enviada em uma mensagem separada.' },
  { id: 'completo',  titulo: '📘 Texto completo', ajuda: 'Todo o conteúdo, dividido em partes se ficar longo.' },
];

export default async function extrairPdf(interaction) {
  // -------------------------------------------
  // 1️⃣  Valida o link informado
  // -------------------------------------------
  const link = interaction.options.getString('link', true);

  if (!/\.pdf$/i.test(link)) {
    throw new ErroUso('O link precisa terminar em **.pdf** (ex.: https://exemplo.com/arquivo.pdf)');
  }
  if (!/^https?:\/\/|^[^.]+\.pdf$/.test(link)) {
    throw new ErroUso('Use um link de internet válido, começando com https://');
  }

  // -------------------------------------------
  // 2️⃣  Lê o modo desejado (robusto para qualquer resolução)
  // -------------------------------------------
  const opcoes = interaction.options.data.filter((o) => o.name === 'modo');
  const modo = opcoes.length ? opcoes[0].value : 'resumo';

  // -------------------------------------------
  // 3️⃣  Aviso inicial "Processando…"
  // -------------------------------------------
  const cana = interaction.channel;
  const aviso = modo === 'todas' ? '⏳ Enviando as seções uma a uma…' : '⏳ Processando o documento…';

  await cana.send({ content: `⏳ ${aviso}\n📎 <${link}>` });

  // -------------------------------------------
  // 4️⃣  Chama a sua API
  // -------------------------------------------
  let dados;
  try {
    dados = await buscarLinkNaApi(link);
  } catch (err) {
    console.error('[extrair-pdf] Erro na API:', err);
    await cana.send({
      content: `❌ **Erro ao falar com a API:** ${err.message}`,
      ephemeral: true,
    });
    throw err; // o router pega e mostra um erro padrão amigável
  }

  const agora = Date.now();
  const meta = normalizarDados(dados);
  const secoes = normalizarSecoes(dados);

  // origem do documento para links clicáveis
  const origem = limpar(
    String(((dados.meta?.urlOrigem || dados.meta?.url || dados.url || dados.link || dados.source || '').trim()) || '')
  );

  if (modo === 'resumo')      await realizarResumo(interaction, cana, agora, meta, secoes, origem);
  else if (modo === 'todas')  await enviarTodasAsSecoes(secoes, interaction, cana, origem, agora);
  else                        await enviarTextoIntegral(dados, interaction, cana, agora, origem);
}

// ---------------------------- LINK CLICÁVEL ----------------------------
function linkCliavel(url) {
  return (url.startsWith('http:') || url.startsWith('https:')) && url.length > 15
    ? `[${url}](${url})`
    : url;
}

// ---------------------------- MODO: RESUMO ----------------------------
async function realizarResumo(intAct, cana, inicio, meta, secoes, origem) {
  const fim = Date.now();
  const duracao = duracaoHumana(fim - inicio) || '—';
  const nPalavras = secoes.reduce((s, sec) => s + totalPalavras(sec.trecho), 0);

  const secaoCampos = secoes.slice(0, 8).map((sec, idx) => ({
    name: `**§${idx + 1}. ${escapar(limpa(sec.titulo))}`,
    value: escapar(limpa(quebrarLinhas(sec.trecho, 110))),
    inline: false,
  }));

  const campos = [
    { name: '**📄 Título:**',       value: escapar(limpa(meta.titulo || 'Sem título')),            inline: true },
    { name: '**✍️ Autor:**',        value: escapar(limpa(meta.autor || 'Autor não informado')),    inline: true },
    { name: '**🖨️ Páginas:**',      value: meta.paginas != null ? `**${Number(meta.paginas)} página(s)**` : '—', inline: true },
    { name: `**⏱️ Tempo:**`,        value: duracao,                                              inline: true },
    { name: `**📚 Seções:**`,        value: valorSecoes(secoes),                                  inline: true },
    { name: '**🔗 Abrir no navegador:**', value: linkCliavel(origem),                               inline: false },
  ];

  const descResumo = meta.resumo
    ? `Segue o resumo:\n\n> ${limpar(escapar(quebrarLinhas(meta.resumo, 280)))}`
    : 'Resumo indisponível nesta extração.';

  const extras = secoes.length > 8
    ? `\n\n📂 Ainda há **${secoes.length - 8} seção(ões)** — use \`/extrair-pdf <link> todas\` para vê-las.`
    : '';

  const embed = new Embed()
    .setTitle(escapar(limpa(limpa(meta.titulo || '📄 Informações do documento extraído'))))
    .setDescription(descResumo + extras)
    .addFields(...campos, ...secaoCampos)
    .setTimestamp()
    .setFooter({ text: origem ? `Fonte: ${escapar(limpa(origem))}` : 'Extração automática' })
    .setColor(settings.cores.documents)
    .setAuthor(interaction.user.username, undefined, new Date(intAct.user.createdAt));

  await cana.send(embed);
}

function valorSecoes(secoes) {
  if (!secoes.length) return '—';
  const n = secoes.reduce((s, x) => s + totalPalavras(x.trecho), 0);
  return n >= 1000
    ? `**${Math.round(n / 1000)}k palavras** em ${secoes.length} seções`
    : `**~${Math.round(n)} palavras** em ${secoes.length} seções`;
}

// ---------------------------- MODO: TODAS AS SEÇÕES ----------------------------
async function enviarTodasAsSecoes(secoes, intAct, cana, origem, inicio) {
  const total = secoes.length;
  if (!total) {
    await cana.send({
      content: '⚠️ Nenhuma seção disponível nesta extração. Tente outro link.',
      ephemeral: true,
    });
    return;
  }

  await cana.send(`⏳ Enviando **${total} seções**…`);

  const mensagens = [];
  for (let i = 0; i < total; i++) {
    const palavras = totalPalavras(secoes[i].trecho);
    mensagens.push(
      await cana.send(`➡️ **Seção ${i + 1} de ${total} — ${secoes[i].titulo}**\n⚪ ${palavras} palavras`)
    );
    if (i < total - 1) await dormir(500); // espaça para não estourar rate limit
  }

  // atualiza a última mensagem com o ✅ final
  if (mensagens.length) {
    await mensagens[mensagens.length - 1].edit({
      content: `✅ **Pronto!** Enviadas as **${total} seções**.\n🔗 ${origem ? limp(origem) : '—'}\n💡 Quer só o resumo? Use \`/extrair-pdf <link> resumo\``,
    });
  }
}

// ---------------------------- MODO: TEXTO COMPLETO ----------------------------
async function enviarTextoIntegral(dados, intAct, cana, inicio, origem) {
  const texto = obterTextoCompleto(dados);
  const limite = settings.maxFullTextPerMsg || 1700; // respeita o limite de 2000 chars do Discord
  const totalChars = texto.length;
  const totalPartes = totalChars > 0 ? Math.max(1, Math.ceil(totalChars / limite)) : 0;

  // sem texto integral? cai para o resumo
  if (!texto) {
    await cana.send({
      content: '⚠️ A API não retornou o texto integral. Mostrarei o resumo em vez disso.',
      ephemeral: true,
    });
    // fallback automático: gera o resumo normalmente
    const helpers = await import('../helpers.js');
    await realizarResumo(intAct, cana, Date.now(), helpers.normalizarDados(dados), helpers.normalizarSecoes(dados), origem);
    return;
  }

  await cana.send(`⏳ Enviando o **texto completo** (${totalChars.toLocaleString()} caracteres → ${totalPartes} partes)…`);

  let k = 0;
  while (k < totalPartes) {
    const ini = k * limite;
    const fim = Math.min(ini + limite, totalChars);
    const bloco = texto.slice(ini, fim);
    const sufixo = k < totalPartes - 1 ? `\n❧ *(continua…)*` : '';
    const mensagem = `❧ **Parte ${k + 1} de ${totalPartes}**\n${escapar(limpa(bloco))}${sufixo}`.slice(0, 1850);

    await cana.send(mensagem);
    k += limite;
    if (k < totalPartes) await dormir(300); // ritmo confortável
  }

  await cana.send(`✅ **Concluído!**\n📄 Total: ${totalChars.toLocaleString()} caracteres · ${totalPartes} partes enviadas.\n🔗 ${origem ? limp(origem) : ''}`);
}

function limp(x) { return limpar(escapar(x)); }
```

